-- Synthetic DEV-only transaction. No message functions are invoked. Everything rolls back.
begin;
do $$
declare c uuid:=gen_random_uuid();v uuid:=gen_random_uuid();s uuid:=gen_random_uuid();o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();grp uuid:=gen_random_uuid();a uuid;admin_id uuid;net integer;n integer;before_count integer;i integer;visits integer;
begin
 insert into public.clients(id,name,email) values(c,'LOYALTY_SYNTHETIC_ONLY','synthetic@example.invalid');
 select id into a from public.loyalty_accounts where client_id=c;
 if a is null then raise exception 'FAIL automatic membership';end if;
 if not exists(select 1 from public.notification_consents where client_id=c and email_opt_in and whatsapp_opt_in) then raise exception 'FAIL default preferences';end if;
 update public.clients set email_opt_in=false where id=c;
 if exists(select 1 from public.notification_consents where client_id=c and email_opt_in) then raise exception 'FAIL client opt-out mirror';end if;
 update public.notification_consents set whatsapp_opt_in=false where client_id=c;
 if exists(select 1 from public.clients where id=c and whatsapp_opt_in) then raise exception 'FAIL integration mirror';end if;
 insert into public.vehicles(id,client_id,plate) values(v,c,'TEST-'||left(c::text,8));
 insert into public.service_types(id,name,price) values(s,'SYNTHETIC_SERVICE',999);
 insert into public.service_orders(id,vehicle_id,service_id,status,charged_amount,completed_at,atendimento_id) values(o,v,s,'concluido',65.99,now(),grp);
 select points_balance into net from public.loyalty_accounts where id=a;if net<>65 then raise exception 'FAIL billed amount floor: %',net;end if;
 select count(*) into before_count from public.loyalty_transactions where account_id=a;
 perform private.sync_service_loyalty(o);perform private.sync_service_loyalty(o);
 select count(*) into n from public.loyalty_transactions where account_id=a;if n<>before_count then raise exception 'FAIL duplicate award';end if;
 update public.service_orders set charged_amount=70 where id=o;
 select points_balance into net from public.loyalty_accounts where id=a;if net<>70 then raise exception 'FAIL amount adjustment';end if;
 update public.service_orders set status='cancelado' where id=o;
 select points_balance into net from public.loyalty_accounts where id=a;if net<>0 then raise exception 'FAIL canceled adjustment';end if;
 update public.service_orders set status='concluido' where id=o;
 insert into public.service_orders(id,vehicle_id,service_id,status,charged_amount,completed_at,atendimento_id) values(o2,v,s,'concluido',3000,now(),grp);
 select visits_in_window into visits from public.loyalty_overview where client_id=c;if visits<>1 then raise exception 'FAIL grouped visit: %',visits;end if;
 select id into admin_id from public.profiles where role='administrador' limit 1;
 if admin_id is null then raise exception 'FAIL missing DEV test role';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 perform public.redeem_loyalty_reward(c,'simple_no_wax','Synthetic validation');
 select points_balance into net from public.loyalty_accounts where id=a;if net<>2070 then raise exception 'FAIL redemption: %',net;end if;
 if (select visits_in_window from public.loyalty_overview where client_id=c)<>1 then raise exception 'FAIL redemption affected VIP';end if;
 delete from public.service_orders where id=o2;
 if not exists(select 1 from public.loyalty_accounts where id=a and points_balance=0 and points_debt=930) then raise exception 'FAIL reversal after redemption';end if;
 begin perform public.redeem_loyalty_reward(c,'simple_no_wax','');raise exception 'FAIL overspend accepted'; exception when others then if sqlerrm='FAIL overspend accepted' then raise;end if;end;
 insert into public.service_orders(vehicle_id,service_id,status,charged_amount,completed_at) values(v,s,'concluido',1000,now());
 if not exists(select 1 from public.loyalty_accounts where id=a and points_balance=70 and points_debt=0) then raise exception 'FAIL debt offset';end if;
 update public.loyalty_settings set points_per_real=2 where id=1;
 insert into public.service_orders(vehicle_id,service_id,status,charged_amount,completed_at) values(v,s,'concluido',65,now());
 select points_balance into net from public.loyalty_accounts where id=a;if net<>200 then raise exception 'FAIL configurable rate: %',net;end if;
 update public.service_orders set charged_amount=80 where id=o;
 select points_balance into net from public.loyalty_accounts where id=a;if net<>210 then raise exception 'FAIL original rate not preserved: %',net;end if;
 insert into public.service_orders(vehicle_id,service_id,status,charged_amount,completed_at) values(v,s,'concluido',0,now());
 select points_balance into net from public.loyalty_accounts where id=a;if net<>210 then raise exception 'FAIL free service award';end if;
 for i in 1..6 loop insert into public.service_orders(vehicle_id,service_id,status,charged_amount,completed_at) values(v,s,'concluido',0,now());end loop;
 if (select vip_tier from public.loyalty_overview where client_id=c)<>'diamante' then raise exception 'FAIL recurrence tier';end if;
 select visits_in_window into visits from public.loyalty_overview where client_id=c;
 insert into public.service_orders(vehicle_id,service_id,status,charged_amount,completed_at) values(v,s,'concluido',0,now()-interval '120 days');
 if (select visits_in_window from public.loyalty_overview where client_id=c)<>visits then raise exception 'FAIL old visit included';end if;
 if (select sum(points_delta) from public.loyalty_transactions where account_id=a)<>(select points_balance-points_debt from public.loyalty_accounts where id=a) then raise exception 'FAIL ledger reconciliation';end if;
 execute 'set local role authenticated';
 begin insert into public.loyalty_transactions(account_id,points_delta,reason) values(a,10000,'FORGED');raise exception 'FAIL direct credit accepted';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $$;
select 'PASS: 19 automatic loyalty, preference, recurrence, redemption and authorization checks' result;
rollback;
